import pandas as pdimport matplotlib.pyplot as pltimport seaborn as snsprint("Loading the gene expression dataset...")# 1. Load the sample CSV file# index_col=0 makes the first column (Gene names) act as row headersdata = pd.read_csv("sample_data.csv", index_col=0)print("\n--- Raw Gene Expression Data ---")print(data)# 2. Transpose data so genes become columns and samples become rowstransposed_data = data.T# 3. Calculate Pearson correlation between genescorrelation_matrix = transposed_data.corr(method='pearson')print("\n--- Gene Correlation Matrix ---")print(correlation_matrix)# 4. Plot the heatmapprint("\nGenerating heatmap window...")plt.figure(figsize=(6, 5))sns.heatmap(correlation_matrix, annot=True, cmap='coolwarm', vmin=-1, vmax=1)plt.title("Gene Co-expression Heatmap")plt.xlabel("Genes")plt.ylabel("Genes")# Show the plot pop-up windowplt.show()